function a(t){if(!t)return"";try{const r=new Date(t);return`${String(r.getDate()).padStart(2,"0")}/${String(r.getMonth()+1).padStart(2,"0")}/${r.getFullYear()}`}catch{return t}}function e(t){try{const r=Number(t);return isNaN(r)?t:`${r<0?"-":""}R$${Math.abs(r).toFixed(2).replace(".",",")}`}catch{return t}}function o(t){return["Jan","Fev","Mar","Abr","Mai","Jun","Jul","Ago","Set","Out","Nov","Dec"][t]||""}function s(t){const r=String(t||"").trim().toLowerCase();return r==="saída"||r==="saida"}export{a,e as f,o as g,s as i};
